def digests(root: Path) -> dict[str, str]:
    """SHA-256 of every file under root (relative posix path), except the manifest."""
    return {
        p.relative_to(root).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
        for p in sorted(root.rglob("*"))
        if p.is_file() and p.name != "manifest.json"
    }


@pytest.mark.parametrize("writer", ["ome_zarr", "tiff"])
def test_small_design_is_byte_identical(tmp_path, writer):
    design = load_design(bundled_designs()["small"].read_text())
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", message="cell_plate", category=UserWarning)
        CellPlateGenerator().generate(design, tmp_path / "d", writer=writer)
    assert digests(tmp_path / "d") == EXPECTED[writer]
